import { tags } from "typia";

/**
 * Comprehensive summary of the customer's wishlist activity, including total
 * counts and out-of-stock indicators. This DTO represents the response from the
 * GET /shoppingMall/customer/wishlists/summary endpoint, providing key metrics
 * without exposing individual item details to maintain customer privacy.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallWishlistSummary = {
  /**
   * Total number of wishlist collections owned by the authenticated customer.
   *
   * This count represents the number of distinct wishlist entities created in
   * the shopping_mall_wishlists table for the authenticated user. Each
   * wishlist may contain zero or more wishlist items and serves as a
   * container for saved product variants.
   *
   * This metric helps customers understand how many separate wishlists they
   * have created to organize their saved items.
   *
   * Calculated by counting records in the shopping_mall_wishlists table where
   * owner_id matches the authenticated user's ID.
   */
  total_wishlists: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Total number of wishlist items across all of the customer's wishlist
   * collections.
   *
   * This represents the aggregate count of all product variants saved across
   * every wishlist owned by the authenticated customer. Each item corresponds
   * to a single row in the shopping_mall_wishlist_items table.
   *
   * This metric provides insight into the overall volume of items a customer
   * has saved for future consideration, regardless of how they're organized
   * across multiple wishlists.
   *
   * Calculated by counting all rows in the shopping_mall_wishlist_items table
   * linked to the authenticated user's wishlists.
   */
  total_items: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Number of wishlist collections that contain at least one out-of-stock
   * product variant.
   *
   * This metric identifies how many of the customer's wishlists include items
   * that are currently unavailable for purchase.
   *
   * A high out_of_stock_count may indicate a customer is saving items that
   * frequently sell out, or it may suggest timing issues where the customer
   * saved items before they were restocked.
   *
   * This information helps customers prioritize which wishlists to revisit,
   * as items in these wishlists may require additional actions such as
   * setting up availability alerts.
   *
   * Calculated by identifying wishlist collections (shopping_mall_wishlists)
   * that contain one or more items from shopping_mall_wishlist_items where
   * inventory_status is 'out_of_stock'.
   */
  out_of_stock_count: number & tags.Type<"int32"> & tags.Minimum<0>;
};
